import{CONFIG}from '../../common/js/modules/config.min.js';import{UI}from '../../common/js/modules/ui.min.js';import{Renderer}from '../../common/js/modules/renderer.min.js';class PortfolioApp{constructor(){this.data=window.mainPortfolio||[];this.gallery=window.galleryData||[];this.ui=new UI();this.renderer=new Renderer(this.data,this.gallery);setRandomSystemTheme();this.handlePreloader();this.init();}handlePreloader(){const preloader=document.getElementById('preloader');if(sessionStorage.getItem('tarquitet_welcomed')){if(preloader){preloader.style.transition='none';preloader.style.display='none';}document.body.classList.remove('loading');}else{sessionStorage.setItem('tarquitet_welcomed','true');}}init(){try{this.renderer.renderAll();this.ui.initAll();let resizeTimer;let windowWidth=window.innerWidth;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(window.innerWidth!==windowWidth){windowWidth=window.innerWidth;this.renderer.renderAll();}},200);});const yearEl=document.getElementById(CONFIG.DOM.footerYear);if(yearEl)yearEl.textContent=new Date().getFullYear();}catch(error){console.error('ERROR CRÍTICO EN MAIN:',error);document.body.classList.remove('loading');const pl=document.getElementById('preloader');if(pl)pl.style.display='none';}}}function setRandomSystemTheme(){const darkThemes=['theme-fire','theme-industrial','theme-cyber'];const lightThemes=['theme-bauhaus','theme-pop'];const isDarkMode=window.matchMedia('(prefers-color-scheme: dark)').matches;const themeCatalog=isDarkMode?darkThemes:lightThemes;const randomIndex=Math.floor(Math.random()*themeCatalog.length);const selectedTheme=themeCatalog[randomIndex];document.documentElement.setAttribute('data-theme',selectedTheme);const themeButtons=document.querySelectorAll('.theme-btn');themeButtons.forEach((btn)=>{btn.classList.remove('active');if(btn.dataset.theme===selectedTheme){btn.classList.add('active');}});}document.addEventListener('DOMContentLoaded',()=>new PortfolioApp());